export enum ShipmentStatus {
  PENDING = 'PENDING',
  IN_TRANSIT = 'IN_TRANSIT',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

export interface Shipment {
  id: string;
  origin: string;
  destination: string;
  driverName: string;
  cargoType: string;
  weight: number; // in kg
  date: string;
  status: ShipmentStatus;
  notes?: string;
  priority: 'Baja' | 'Media' | 'Alta';
}

export interface DashboardStats {
  totalShipments: number;
  inTransit: number;
  deliveredToday: number;
  totalWeight: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Shipment } from "../types";

export const getLogisticsInsights = async (shipments: Shipment[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Analiza la siguiente lista de envíos logísticos y proporciona un resumen ejecutivo breve (máximo 150 palabras). 
  Identifica posibles cuellos de botella, sugiere prioridades para el día y da un consejo de optimización de rutas.

  Datos: ${JSON.stringify(shipments)}

  Responde en un formato profesional y amigable en español.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        temperature: 0.7,
        topP: 0.95,
      }
    });
    return response.text;
  } catch (error) {
    console.error("Error fetching Gemini insights:", error);
    return "No se pudieron obtener insights de IA en este momento. Por favor, verifica tu conexión o configuración.";
  }
};

