import React, { useState, useEffect } from 'react';
import { Shipment, ShipmentStatus } from '../types';

interface ShipmentModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (shipment: Shipment) => void;
  initialData?: Shipment | null;
}

const ShipmentModal: React.FC<ShipmentModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [formData, setFormData] = useState<Partial<Shipment>>({
    origin: '',
    destination: '',
    driverName: '',
    cargoType: '',
    weight: 0,
    date: new Date().toISOString().split('T')[0],
    status: ShipmentStatus.PENDING,
    priority: 'Media',
    notes: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        origin: '',
        destination: '',
        driverName: '',
        cargoType: '',
        weight: 0,
        date: new Date().toISOString().split('T')[0],
        status: ShipmentStatus.PENDING,
        priority: 'Media',
        notes: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalData = {
      ...formData,
      id: initialData?.id || Math.random().toString(36).substr(2, 9),
    } as Shipment;
    onSave(finalData);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden">
        <div className="bg-slate-50 px-6 py-4 border-b flex justify-between items-center">
          <h2 className="text-lg font-bold text-slate-800">
            {initialData ? 'Editar Envío' : 'Registrar Nuevo Envío'}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            ✕
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Origen</label>
              <input
                required
                type="text"
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.origin}
                onChange={(e) => setFormData({ ...formData, origin: e.target.value })}
                placeholder="Ej. CDMX"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Destino</label>
              <input
                required
                type="text"
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.destination}
                onChange={(e) => setFormData({ ...formData, destination: e.target.value })}
                placeholder="Ej. Monterrey"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Conductor</label>
              <input
                required
                type="text"
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.driverName}
                onChange={(e) => setFormData({ ...formData, driverName: e.target.value })}
                placeholder="Nombre completo"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha de Salida</label>
              <input
                required
                type="date"
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.date}
                onChange={(e) => setFormData({ ...formData, date: e.target.value })}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Tipo de Carga</label>
              <input
                required
                type="text"
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.cargoType}
                onChange={(e) => setFormData({ ...formData, cargoType: e.target.value })}
                placeholder="Ej. Perecederos"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Peso (kg)</label>
              <input
                required
                type="number"
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.weight}
                onChange={(e) => setFormData({ ...formData, weight: Number(e.target.value) })}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Estado</label>
              <select
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.status}
                onChange={(e) => setFormData({ ...formData, status: e.target.value as ShipmentStatus })}
              >
                <option value={ShipmentStatus.PENDING}>Pendiente</option>
                <option value={ShipmentStatus.IN_TRANSIT}>En Tránsito</option>
                <option value={ShipmentStatus.DELIVERED}>Entregado</option>
                <option value={ShipmentStatus.CANCELLED}>Cancelado</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Prioridad</label>
              <select
                className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
                value={formData.priority}
                onChange={(e) => setFormData({ ...formData, priority: e.target.value as any })}
              >
                <option value="Baja">Baja</option>
                <option value="Media">Media</option>
                <option value="Alta">Alta</option>
              </select>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Notas Adicionales</label>
            <textarea
              className="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
              rows={3}
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              placeholder="Detalles sobre la carga, cliente o instrucciones especiales..."
            />
          </div>
          <div className="pt-4 flex justify-end gap-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
            >
              Cancelar
            </button>
            <button
              type="submit"
              className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors shadow-md font-medium"
            >
              Guardar Registro
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ShipmentModal;

import React, { useState, useEffect } from 'react';
import { getLogisticsInsights } from '../services/geminiService';
import { Shipment } from '../types';

interface AIInsightsProps {
  shipments: Shipment[];
}

const AIInsights: React.FC<AIInsightsProps> = ({ shipments }) => {
  const [insight, setInsight] = useState<string>('');
  const [loading, setLoading] = useState(false);

  const fetchInsights = async () => {
    if (shipments.length === 0) {
      setInsight('Agregue algunos envíos para obtener insights de la IA.');
      return;
    }
    setLoading(true);
    const result = await getLogisticsInsights(shipments);
    setInsight(result || '');
    setLoading(false);
  };

  useEffect(() => {
    fetchInsights();
  }, [shipments.length]);

  return (
    <div className="bg-gradient-to-br from-indigo-50 to-blue-50 rounded-xl p-6 border border-indigo-100 shadow-sm">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-bold text-indigo-900 flex items-center gap-2">
          <span className="text-2xl">✨</span> Asistente Logístico AI
        </h3>
        <button 
          onClick={fetchInsights}
          disabled={loading}
          className="text-indigo-600 hover:text-indigo-800 text-sm font-medium disabled:opacity-50"
        >
          {loading ? 'Analizando...' : 'Actualizar Insights'}
        </button>
      </div>

      {loading ? (
        <div className="space-y-3 animate-pulse">
          <div className="h-4 bg-indigo-200 rounded w-full"></div>
          <div className="h-4 bg-indigo-200 rounded w-5/6"></div>
          <div className="h-4 bg-indigo-200 rounded w-4/6"></div>
        </div>
      ) : (
        <div className="text-slate-700 leading-relaxed text-sm whitespace-pre-wrap">
          {insight}
        </div>
      )}

      {!loading && insight && (
        <div className="mt-4 pt-4 border-t border-indigo-200 flex items-center gap-2 text-xs text-indigo-500 italic">
          💡 Generado por Gemini 3 Flash para optimización logística.
        </div>
      )}
    </div>
  );
};

export default AIInsights;

import React, { useState, useEffect, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import ShipmentModal from './components/ShipmentModal';
import AIInsights from './components/AIInsights';
import { Shipment, ShipmentStatus } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'agenda' | 'drivers'>('dashboard');
  const [shipments, setShipments] = useState<Shipment[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentShipment, setCurrentShipment] = useState<Shipment | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Initial Mock Data
  useEffect(() => {
    const saved = localStorage.getItem('logitrack_shipments');
    if (saved) {
      setShipments(JSON.parse(saved));
    } else {
      const mockShipments: Shipment[] = [
        {
          id: '1',
          origin: 'CDMX',
          destination: 'Monterrey',
          driverName: 'Juan Pérez',
          cargoType: 'Electrónicos',
          weight: 1200,
          date: '2024-05-20',
          status: ShipmentStatus.IN_TRANSIT,
          priority: 'Alta'
        },
        {
          id: '2',
          origin: 'Guadalajara',
          destination: 'Querétaro',
          driverName: 'Ana García',
          cargoType: 'Alimentos',
          weight: 800,
          date: '2024-05-21',
          status: ShipmentStatus.PENDING,
          priority: 'Media'
        }
      ];
      setShipments(mockShipments);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('logitrack_shipments', JSON.stringify(shipments));
  }, [shipments]);

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return {
      total: shipments.length,
      inTransit: shipments.filter(s => s.status === ShipmentStatus.IN_TRANSIT).length,
      delivered: shipments.filter(s => s.status === ShipmentStatus.DELIVERED).length,
      totalWeight: shipments.reduce((acc, curr) => acc + curr.weight, 0)
    };
  }, [shipments]);

  const filteredShipments = useMemo(() => {
    return shipments.filter(s => 
      s.driverName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      s.origin.toLowerCase().includes(searchTerm.toLowerCase()) ||
      s.destination.toLowerCase().includes(searchTerm.toLowerCase()) ||
      s.cargoType.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [shipments, searchTerm]);

  const handleSaveShipment = (shipment: Shipment) => {
    if (currentShipment) {
      setShipments(prev => prev.map(s => s.id === shipment.id ? shipment : s));
    } else {
      setShipments(prev => [...prev, shipment]);
    }
    setIsModalOpen(false);
    setCurrentShipment(null);
  };

  const handleDeleteShipment = (id: string) => {
    if (window.confirm('¿Está seguro de que desea eliminar este registro?')) {
      setShipments(prev => prev.filter(s => s.id !== id));
    }
  };

  const openEditModal = (shipment: Shipment) => {
    setCurrentShipment(shipment);
    setIsModalOpen(true);
  };

  const getStatusColor = (status: ShipmentStatus) => {
    switch (status) {
      case ShipmentStatus.PENDING: return 'bg-yellow-100 text-yellow-800';
      case ShipmentStatus.IN_TRANSIT: return 'bg-blue-100 text-blue-800';
      case ShipmentStatus.DELIVERED: return 'bg-green-100 text-green-800';
      case ShipmentStatus.CANCELLED: return 'bg-red-100 text-red-800';
      default: return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="flex min-h-screen">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />

      <main className="flex-1 ml-64 p-8">
        <header className="flex justify-between items-center mb-8">
          <div>
            <h2 className="text-2xl font-bold text-slate-800">
              {activeTab === 'dashboard' && 'Panel de Control'}
              {activeTab === 'agenda' && 'Agenda Logística'}
              {activeTab === 'drivers' && 'Gestión de Conductores'}
            </h2>
            <p className="text-slate-500">Bienvenido de nuevo, Administrador</p>
          </div>
          <button 
            onClick={() => { setCurrentShipment(null); setIsModalOpen(true); }}
            className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-lg shadow-lg font-medium transition-all flex items-center gap-2"
          >
            <span>+</span> Nuevo Envío
          </button>
        </header>

        {activeTab === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              {[
                { label: 'Total Envíos', value: stats.total, icon: '📦', color: 'bg-blue-500' },
                { label: 'En Tránsito', value: stats.inTransit, icon: '🚛', color: 'bg-indigo-500' },
                { label: 'Entregados', value: stats.delivered, icon: '✅', color: 'bg-green-500' },
                { label: 'Carga Total (kg)', value: stats.totalWeight, icon: '⚖️', color: 'bg-orange-500' },
              ].map((stat, i) => (
                <div key={i} className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-center gap-4">
                  <div className={`${stat.color} text-white p-3 rounded-lg text-2xl shadow-inner`}>
                    {stat.icon}
                  </div>
                  <div>
                    <p className="text-sm text-slate-500 font-medium">{stat.label}</p>
                    <p className="text-2xl font-bold text-slate-800">{stat.value}</p>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                  <h3 className="font-bold text-slate-800">Envíos Recientes</h3>
                  <button onClick={() => setActiveTab('agenda')} className="text-blue-600 text-sm font-medium">Ver todos</button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-semibold">
                      <tr>
                        <th className="px-6 py-4">Destino</th>
                        <th className="px-6 py-4">Conductor</th>
                        <th className="px-6 py-4">Estado</th>
                        <th className="px-6 py-4">Prioridad</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {shipments.slice(-5).reverse().map((s) => (
                        <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                          <td className="px-6 py-4">
                            <div className="font-medium text-slate-800">{s.destination}</div>
                            <div className="text-xs text-slate-400">Desde: {s.origin}</div>
                          </td>
                          <td className="px-6 py-4 text-sm text-slate-600">{s.driverName}</td>
                          <td className="px-6 py-4">
                            <span className={`text-xs px-2.5 py-1 rounded-full font-medium ${getStatusColor(s.status)}`}>
                              {s.status.replace('_', ' ')}
                            </span>
                          </td>
                          <td className="px-6 py-4">
                            <span className={`text-xs font-semibold ${
                              s.priority === 'Alta' ? 'text-red-500' : 
                              s.priority === 'Media' ? 'text-orange-500' : 'text-slate-400'
                            }`}>
                              {s.priority}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              <div className="space-y-6">
                <AIInsights shipments={shipments} />
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                  <h3 className="font-bold text-slate-800 mb-4">Meta Diaria de Entregas</h3>
                  <div className="relative pt-1">
                    <div className="flex mb-2 items-center justify-between">
                      <div>
                        <span className="text-xs font-semibold inline-block py-1 px-2 uppercase rounded-full text-blue-600 bg-blue-200">
                          Progreso
                        </span>
                      </div>
                      <div className="text-right">
                        <span className="text-xs font-semibold inline-block text-blue-600">
                          {Math.round((stats.delivered / (stats.total || 1)) * 100)}%
                        </span>
                      </div>
                    </div>
                    <div className="overflow-hidden h-2 mb-4 text-xs flex rounded bg-blue-100">
                      <div style={{ width: `${(stats.delivered / (stats.total || 1)) * 100}%` }} className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-blue-500 transition-all duration-500"></div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'agenda' && (
          <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row gap-4 justify-between items-center">
              <div className="relative w-full md:w-96">
                <span className="absolute left-3 top-2.5 text-slate-400">🔍</span>
                <input 
                  type="text"
                  placeholder="Buscar por conductor, origen, destino..."
                  className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
              <div className="flex gap-2">
                 {/* Filters could go here */}
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-semibold">
                  <tr>
                    <th className="px-6 py-4">ID</th>
                    <th className="px-6 py-4">Ruta (Origen-Destino)</th>
                    <th className="px-6 py-4">Conductor</th>
                    <th className="px-6 py-4">Tipo Carga</th>
                    <th className="px-6 py-4">Peso</th>
                    <th className="px-6 py-4">Fecha</th>
                    <th className="px-6 py-4">Estado</th>
                    <th className="px-6 py-4">Acciones</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {filteredShipments.length > 0 ? filteredShipments.map((s) => (
                    <tr key={s.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-6 py-4 text-xs font-mono text-slate-400">#{s.id.slice(0,6)}</td>
                      <td className="px-6 py-4">
                        <div className="font-medium text-slate-800">{s.origin} → {s.destination}</div>
                      </td>
                      <td className="px-6 py-4 text-sm text-slate-600">{s.driverName}</td>
                      <td className="px-6 py-4 text-sm text-slate-600">{s.cargoType}</td>
