import { GoogleGenAI } from "@google/genai";
import { LogisticsContact } from "../types";

export const getContactInsights = async (contacts: LogisticsContact[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Analiza la siguiente agenda de contactos logísticos y proporciona un resumen ejecutivo (máximo 120 palabras). 
  Identifica si hay un equilibrio entre conductores y clientes, sugiere a quién contactar basándote en la prioridad y da un consejo sobre gestión de redes logísticas.

  Datos: ${JSON.stringify(contacts)}

  Responde en un formato profesional, estructurado y amigable en español.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        temperature: 0.7,
      }
    });
    return response.text;
  } catch (error) {
    console.error("Error fetching Gemini insights:", error);
    return "No se pudieron obtener insights de IA sobre tus contactos en este momento.";
  }
};

