import React, { useState, useEffect } from 'react';
import { getContactInsights } from '../services/geminiService';
import { LogisticsContact } from '../types';

interface AIInsightsProps {
  contacts: LogisticsContact[];
}

const AIInsights: React.FC<AIInsightsProps> = ({ contacts }) => {
  const [insight, setInsight] = useState<string>('');
  const [loading, setLoading] = useState(false);

  const fetchInsights = async () => {
    if (contacts.length === 0) {
      setInsight('Agrega contactos a tu agenda para que la IA pueda analizarlos.');
      return;
    }
    setLoading(true);
    const result = await getContactInsights(contacts);
    setInsight(result || '');
    setLoading(false);
  };

  useEffect(() => {
    fetchInsights();
  }, [contacts.length]);

  return (
    <div className="bg-white rounded-2xl p-6 border border-slate-100 shadow-sm relative overflow-hidden group">
      <div className="absolute top-0 right-0 p-4 opacity-5">
        <span className="text-8xl">🧠</span>
      </div>
      <div className="flex items-center justify-between mb-4 relative z-10">
        <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
          <span className="text-blue-500">✨</span> Análisis de Red Logística
        </h3>
        <button 
          onClick={fetchInsights}
          disabled={loading}
          className="text-blue-600 hover:text-blue-800 text-sm font-bold disabled:opacity-50 transition-colors"
        >
          {loading ? 'Consultando...' : 'Recalcular'}
        </button>
      </div>

      {loading ? (
        <div className="space-y-3 animate-pulse">
          <div className="h-4 bg-slate-100 rounded w-full"></div>
          <div className="h-4 bg-slate-100 rounded w-5/6"></div>
          <div className="h-4 bg-slate-100 rounded w-4/6"></div>
        </div>
      ) : (
        <div className="text-slate-600 leading-relaxed text-sm whitespace-pre-wrap relative z-10">
          {insight}
        </div>
      )}

      {!loading && insight && (
        <div className="mt-4 pt-4 border-t border-slate-50 flex items-center gap-2 text-[10px] text-slate-400 font-medium">
          Powered by Gemini 3 Flash Intelligence
        </div>
      )}
    </div>
  );
};

