                  {role === ContactRole.DRIVER && '🚛'}
                  {role === ContactRole.CLIENT && '💼'}
                  {role === ContactRole.SUPPLIER && '🏭'}
                  {role === ContactRole.DISPATCHER && '🎧'}
                  {role === ContactRole.PARTNER && '🤝'}
                </div>
                <h4 className="text-xl font-black text-slate-800 mb-2">{role}s</h4>
