                      <td className="px-8 py-5">
                        <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => openEditModal(c)}
                            className={`p-2 rounded-lg transition-colors ${darkMode ? 'text-blue-400 hover:bg-blue-900/30' : 'text-blue-600 hover:bg-blue-100'}`}
                            title="Editar Datos"
                          >
                            ✏️
                          </button>
                          <button 
                            onClick={() => handleDeleteContact(c.id)}
                            className={`p-2 rounded-lg transition-colors ${darkMode ? 'text-rose-400 hover:bg-rose-900/30' : 'text-red-600 hover:bg-red-100'}`}
                            title="Eliminar de Agenda"
                          >
                            🗑️
                          </button>
                        </div>
                      </td>
                    </tr>
                  )) : (
                    <tr>
                      <td colSpan={5} className="px-8 py-20 text-center text-slate-500 italic">
                        No hay contactos que coincidan con la búsqueda.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>

      <ContactModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveContact}
        initialData={currentContact}
        darkMode={darkMode}
      />
    </div>
  );
};

export default App;

