import React, { useState, useEffect } from 'react';
import { getContactInsights } from '../services/geminiService';
import { LogisticsContact } from '../types';

interface AIInsightsProps {
  contacts: LogisticsContact[];
  darkMode?: boolean;
}

const AIInsights: React.FC<AIInsightsProps> = ({ contacts, darkMode }) => {
  const [insight, setInsight] = useState<string>('');
  const [loading, setLoading] = useState(false);

  const fetchInsights = async () => {
    if (contacts.length === 0) {
      setInsight('Agrega contactos a tu agenda para que la IA pueda analizarlos.');
      return;
    }
    setLoading(true);
    const result = await getContactInsights(contacts);
    setInsight(result || '');
    setLoading(false);
  };

  useEffect(() => {
    fetchInsights();
  }, [contacts.length]);

  return (
    <div className={`rounded-2xl p-6 border shadow-sm relative overflow-hidden group transition-all ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
      <div className="absolute top-0 right-0 p-4 opacity-5">
        <span className="text-8xl">🧠</span>
      </div>
      <div className="flex items-center justify-between mb-4 relative z-10">
        <h3 className={`text-lg font-bold flex items-center gap-2 ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>
          <span className="text-blue-500">✨</span> Análisis IA
        </h3>
        <button 
          onClick={fetchInsights}
          disabled={loading}
          className="text-blue-500 hover:text-blue-400 text-sm font-bold disabled:opacity-50 transition-colors"
        >
          {loading ? '...' : 'Actualizar'}
        </button>
      </div>

      {loading ? (
        <div className="space-y-3 animate-pulse">
          <div className={`h-4 rounded w-full ${darkMode ? 'bg-slate-800' : 'bg-slate-100'}`}></div>
          <div className={`h-4 rounded w-5/6 ${darkMode ? 'bg-slate-800' : 'bg-slate-100'}`}></div>
          <div className={`h-4 rounded w-4/6 ${darkMode ? 'bg-slate-800' : 'bg-slate-100'}`}></div>
        </div>
      ) : (
        <div className={`leading-relaxed text-sm whitespace-pre-wrap relative z-10 ${darkMode ? 'text-slate-400' : 'text-slate-600'}`}>
          {insight}
        </div>
      )}

      {!loading && insight && (
        <div className={`mt-4 pt-4 border-t flex items-center gap-2 text-[10px] font-medium ${darkMode ? 'border-slate-800 text-slate-600' : 'border-slate-50 text-slate-400'}`}>
          Optimizado con Gemini Flash 3
        </div>
      )}
    </div>
  );
};

export default AIInsights;

import React, { useState, useEffect } from 'react';
import { LogisticsContact } from '../types';

interface ContactModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (contact: LogisticsContact) => void;
  initialData?: LogisticsContact | null;
  darkMode?: boolean;
}

const ContactModal: React.FC<ContactModalProps> = ({ isOpen, onClose, onSave, initialData, darkMode }) => {
  const [formData, setFormData] = useState<Partial<LogisticsContact>>({
    name: '',
    company: '',
    phone: '',
    email: '',
    address: '',
    notes: '',
    priority: 'Media'
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        name: '',
        company: '',
        phone: '',
        email: '',
        address: '',
        notes: '',
        priority: 'Media'
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalData = {
      ...formData,
      id: initialData?.id || Math.random().toString(36).substr(2, 9),
      lastContacted: initialData?.lastContacted || new Date().toISOString().split('T')[0]
    } as LogisticsContact;
    onSave(finalData);
  };

  return (
    <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className={`rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden border transition-all ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
        <div className={`px-8 py-5 border-b flex justify-between items-center ${darkMode ? 'bg-slate-800/50 border-slate-800' : 'bg-slate-50 border-slate-200'}`}>
          <h2 className={`text-xl font-bold ${darkMode ? 'text-white' : 'text-slate-800'}`}>
            {initialData ? 'Editar Contacto' : 'Nuevo Contacto Logístico'}
