                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="Ej. Carlos Rodríguez"
              />
            </div>
            <div className="col-span-1 md:col-span-2">
              <label className={`block text-sm font-semibold mb-1.5 ${darkMode ? 'text-slate-400' : 'text-slate-700'}`}>Empresa / Flota</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.company}
                onChange={(e) => setFormData({ ...formData, company: e.target.value })}
                placeholder="Ej. Transportes del Norte"
              />
            </div>
            <div>
              <label className={`block text-sm font-semibold mb-1.5 ${darkMode ? 'text-slate-400' : 'text-slate-700'}`}>Teléfono</label>
              <input
                required
