  const [currentContact, setCurrentContact] = useState<LogisticsContact | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('logicon_theme');
    return saved === 'dark';
  });

  useEffect(() => {
    const saved = localStorage.getItem('logicon_contacts');
    if (saved) {
      setContacts(JSON.parse(saved));
    } else {
      const mockContacts: LogisticsContact[] = [
        {
          id: '1',
          name: 'Ricardo Mendez',
          company: 'Fletes del Centro',
          phone: '+52 555-0192',
          email: 'ricardo.m@fletes.com',
          priority: 'Alta',
          lastContacted: '2024-05-18'
        },
        {
          id: '2',
          name: 'Elena Soto',
          company: 'Distribuidora Global',
          phone: '+52 555-9988',
          email: 'e.soto@global.com',
          priority: 'Media',
          lastContacted: '2024-05-20'
        }
      ];
      setContacts(mockContacts);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('logicon_contacts', JSON.stringify(contacts));
  }, [contacts]);

  useEffect(() => {
    localStorage.setItem('logicon_theme', darkMode ? 'dark' : 'light');
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const stats = useMemo(() => {
    const priorityCount = contacts.reduce((acc, c) => {
      acc[c.priority] = (acc[c.priority] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    return {
      total: contacts.length,
      high: priorityCount['Alta'] || 0,
      medium: priorityCount['Media'] || 0,
      low: priorityCount['Baja'] || 0
    };
  }, [contacts]);

  const filteredContacts = useMemo(() => {
    return contacts.filter(c => 
      c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.company.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [contacts, searchTerm]);

  const handleSaveContact = (contact: LogisticsContact) => {
    if (currentContact) {
      setContacts(prev => prev.map(c => c.id === contact.id ? contact : c));
    } else {
      setContacts(prev => [...prev, contact]);
    }
    setIsModalOpen(false);
    setCurrentContact(null);
  };

  const handleDeleteContact = (id: string) => {
    if (window.confirm('¿Deseas eliminar este registro permanentemente?')) {
      setContacts(prev => prev.filter(c => c.id !== id));
    }
  };

