    const saved = localStorage.getItem('logicon_theme');
    return saved === 'dark';
  });

  useEffect(() => {
    const saved = localStorage.getItem('logicon_contacts');
    if (saved) {
      setContacts(JSON.parse(saved));
    } else {
      const mockContacts: LogisticsContact[] = [
        {
          id: '1',
          name: 'Ricardo Mendez',
          company: 'Fletes del Centro',
          phone: '+52 555-0192',
          email: 'ricardo.m@fletes.com',
          priority: 'Alta',
          lastContacted: '2024-05-18'
        },
        {
          id: '2',
          name: 'Elena Soto',
          company: 'Distribuidora Global',
          phone: '+52 555-9988',
          email: 'e.soto@global.com',
          priority: 'Media',
          lastContacted: '2024-05-20'
        }
      ];
      setContacts(mockContacts);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('logicon_contacts', JSON.stringify(contacts));
  }, [contacts]);

  useEffect(() => {
    localStorage.setItem('logicon_theme', darkMode ? 'dark' : 'light');
