              <span className={`w-2 h-2 rounded-full bg-blue-500 animate-pulse`}></span>
              <p className={`text-sm font-medium ${darkMode ? 'text-slate-400' : 'text-slate-500'}`}>
                Gestión de contactos
              </p>
            </div>
          </div>
