                      </div>
                      <div className="text-right">
                        <span className={`text-[10px] font-black px-3 py-1 rounded-full mb-1 inline-block ${
                          c.priority === 'Alta' ? 'bg-rose-500/10 text-rose-500' : 
                          c.priority === 'Media' ? 'bg-amber-500/10 text-amber-500' : 'bg-slate-500/10 text-slate-400'
                        }`}>
                          {c.priority.toUpperCase()}
                        </span>
                        <p className={`text-[10px] font-bold ${darkMode ? 'text-slate-600' : 'text-slate-300'}`}>REGISTRADO: {c.lastContacted}</p>
                      </div>
                    </div>
                  ))}
                  {contacts.length === 0 && (
                    <div className="p-16 text-center text-slate-500 text-sm font-medium italic">
                      No hay registros disponibles.
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'agenda' && (
          <div className="space-y-8 animate-in slide-in-from-bottom-8 duration-700">
            <div className={`p-8 rounded-[2rem] border transition-all ${darkMode ? 'bg-slate-900 border-slate-800 shadow-none' : 'bg-white border-slate-100 shadow-xl shadow-slate-200/50'}`}>
              <div className="flex flex-col md:flex-row gap-6 justify-between items-center">
                <div className="relative w-full md:w-96 group">
                  <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
                  </span>
                  <input 
                    type="text"
                    placeholder="Búsqueda avanzada..."
                    className={`w-full pl-14 pr-6 py-4 border rounded-[1.25rem] focus:ring-4 focus:ring-blue-500/10 outline-none transition-all font-semibold ${darkMode ? 'bg-slate-800 border-slate-700 text-white placeholder-slate-500' : 'bg-slate-50 border-slate-100 text-slate-800'}`}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>
                <div className={`flex p-1 rounded-2xl border transition-all ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-slate-100 border-slate-200'}`}>
                  <button 
                    onClick={() => setViewMode('table')}
                    className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'table' ? (darkMode ? 'bg-blue-600 text-white' : 'bg-white text-blue-600 shadow-md') : 'text-slate-400 hover:text-slate-600'}`}
                  >
                    Tabla
                  </button>
                  <button 
                    onClick={() => setViewMode('grid')}
                    className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'grid' ? (darkMode ? 'bg-blue-600 text-white' : 'bg-white text-blue-600 shadow-md') : 'text-slate-400 hover:text-slate-600'}`}
                  >
                    Tarjetas
                  </button>
                </div>
              </div>
            </div>

            {viewMode === 'table' ? (
              <div className={`rounded-[2rem] border transition-all overflow-hidden ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100 shadow-xl shadow-slate-200/50'}`}>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className={`text-[10px] uppercase font-black tracking-[0.25em] ${darkMode ? 'bg-slate-800/50 text-slate-600' : 'bg-slate-50 text-slate-400'}`}>
                      <tr>
                        <th className="px-10 py-6">Socio Logístico</th>
                        <th className="px-10 py-6">Organización</th>
                        <th className="px-10 py-6">Datos de Enlace</th>
                        <th className="px-10 py-6">Prioridad</th>
                        <th className="px-10 py-6 text-right">Acciones</th>
                      </tr>
                    </thead>
                    <tbody className={`divide-y ${darkMode ? 'divide-slate-800' : 'divide-slate-50'}`}>
                      {filteredContacts.length > 0 ? filteredContacts.map((c) => (
                        <tr key={c.id} className={`transition-all group ${darkMode ? 'hover:bg-slate-800/50' : 'hover:bg-blue-50/20'}`}>
                          <td className="px-10 py-7">
                            <div className={`font-bold text-lg ${darkMode ? 'text-slate-100' : 'text-slate-800'}`}>{c.name}</div>
                          </td>
                          <td className="px-10 py-7">
                            <div className={`text-sm font-black uppercase tracking-widest ${darkMode ? 'text-slate-500' : 'text-slate-500'}`}>{c.company}</div>
                          </td>
                          <td className="px-10 py-7">
                            <div className={`text-sm font-bold ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{c.phone}</div>
                            <div className={`text-xs font-medium ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>{c.email}</div>
                          </td>
                          <td className="px-10 py-7">
                            <div className="flex items-center gap-2">
                              <span className={`w-1.5 h-1.5 rounded-full ${
                                c.priority === 'Alta' ? 'bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.4)]' : 
                                c.priority === 'Media' ? 'bg-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.4)]' : 'bg-slate-400'
                              }`}></span>
                              <span className={`text-[10px] font-black uppercase tracking-[0.1em] ${
                                c.priority === 'Alta' ? 'text-rose-500' : 
                                c.priority === 'Media' ? 'text-amber-500' : 'text-slate-500'
                              }`}>
                                {c.priority}
                              </span>
                            </div>
                          </td>
                          <td className="px-10 py-7 text-right">
                            <div className="flex gap-2 justify-end opacity-0 group-hover:opacity-100 transition-all transform translate-x-2 group-hover:translate-x-0">
                              <button 
                                onClick={() => openEditModal(c)}
                                className={`p-3 rounded-xl transition-all ${darkMode ? 'text-blue-400 hover:bg-blue-900/30' : 'text-blue-600 hover:bg-blue-100'}`}
                              >
                                <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 1 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                              </button>
                              <button 
                                onClick={() => handleDeleteContact(c.id)}
                                className={`p-3 rounded-xl transition-all ${darkMode ? 'text-rose-400 hover:bg-rose-900/30' : 'text-red-500 hover:bg-red-100'}`}
                              >
                                <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>
                              </button>
                            </div>
                          </td>
                        </tr>
                      )) : (
                        <tr>
                          <td colSpan={5} className="px-10 py-32 text-center text-slate-500 italic">No hay registros</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {filteredContacts.length > 0 ? filteredContacts.map((c) => (
                  <div key={c.id} className={`group rounded-[2rem] p-8 border transition-all ${darkMode ? 'bg-slate-900 border-slate-800 hover:border-blue-500/50 hover:shadow-2xl hover:shadow-blue-900/20' : 'bg-white border-slate-100 shadow-sm hover:shadow-2xl hover:shadow-slate-200 hover:-translate-y-1'}`}>
                    <div className="flex justify-between items-start mb-6">
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-bold text-lg shadow-inner ${darkMode ? 'bg-[#1a1d23] text-slate-500' : 'bg-slate-100 text-slate-400'}`}>
                        {c.name.split(' ').map(n => n[0]).join('')}
                      </div>
                      <div className="flex gap-2">
                        <button 
                          onClick={() => openEditModal(c)}
                          className={`p-2 rounded-lg transition-colors ${darkMode ? 'text-slate-500 hover:text-blue-400' : 'text-slate-400 hover:text-blue-600'}`}
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 1 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                        </button>
                        <button 
                          onClick={() => handleDeleteContact(c.id)}
                          className={`p-2 rounded-lg transition-colors ${darkMode ? 'text-slate-500 hover:text-rose-400' : 'text-slate-400 hover:text-red-500'}`}
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
                        </button>
                      </div>
                    </div>

                    <h4 className={`text-xl font-black mb-1 ${darkMode ? 'text-white' : 'text-slate-900'}`}>{c.name}</h4>
                    <p className={`text-xs font-black uppercase tracking-widest mb-6 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>{c.company}</p>

                    <div className="space-y-4 mb-8">
                      <div className="flex items-center gap-3">
                        <svg className={`text-blue-500`} xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>
                        <span className={`text-sm font-bold ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{c.phone}</span>
                      </div>
                      <div className="flex items-center gap-3">
                        <svg className={`text-blue-500`} xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>
                        <span className={`text-sm font-medium ${darkMode ? 'text-slate-500' : 'text-slate-500'}`}>{c.email}</span>
                      </div>
                    </div>

                    <div className="flex justify-between items-center pt-6 border-t border-dashed border-slate-200 dark:border-slate-800">
                      <div className="flex items-center gap-2">
                        <span className={`w-1.5 h-1.5 rounded-full ${
                          c.priority === 'Alta' ? 'bg-rose-500' : 
                          c.priority === 'Media' ? 'bg-amber-500' : 'bg-slate-400'
                        }`}></span>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${
                          c.priority === 'Alta' ? 'text-rose-500' : 
                          c.priority === 'Media' ? 'text-amber-500' : 'text-slate-500'
                        }`}>
                          Prioridad {c.priority}
                        </span>
                      </div>
                      <span className={`text-[9px] font-bold ${darkMode ? 'text-slate-600' : 'text-slate-300'}`}>ACTUALIZADO: {c.lastContacted}</span>
                    </div>
                  </div>
                )) : (
                  <div className="col-span-full py-20 text-center text-slate-500 italic">No hay registros</div>
                )}
              </div>
            )}
          </div>
        )}
      </main>

      <ContactModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveContact}
        initialData={currentContact}
        darkMode={darkMode}
      />
    </div>
  );
};

export default App;

export interface LogisticsContact {
  id: string;
  client: string;
  subClient: string;
  contactName: string;
  phone: string;
  altContactName: string;
  altPhone: string;
  city: string;
  address: string;
  unloadingHours: string;
  notes: string;
  priority: 'Baja' | 'Media' | 'Alta';
  lastContacted?: string;
}

export interface ContactStats {
  total: number;
}

export enum ShipmentStatus {
  PENDING = 'Pendiente',
  IN_TRANSIT = 'En Tránsito',
  DELIVERED = 'Entregado',
  CANCELLED = 'Cancelado'
}

export interface Shipment {
  id: string;
  origin: string;
  destination: string;
  driverName: string;
  cargoType: string;
  weight: number;
  date: string;
  status: ShipmentStatus;
  priority: 'Baja' | 'Media' | 'Alta';
  notes?: string;
}

import React, { useState, useEffect } from 'react';
import { LogisticsContact } from '../types';

interface ContactModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (contact: LogisticsContact) => void;
  initialData?: LogisticsContact | null;
  darkMode?: boolean;
}

const ContactModal: React.FC<ContactModalProps> = ({ isOpen, onClose, onSave, initialData, darkMode }) => {
  const [formData, setFormData] = useState<Partial<LogisticsContact>>({
    client: '',
    subClient: '',
    contactName: '',
    phone: '',
    altContactName: '',
    altPhone: '',
    city: '',
    address: '',
    unloadingHours: '',
    notes: '',
    priority: 'Media'
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        client: '',
        subClient: '',
        contactName: '',
        phone: '',
        altContactName: '',
        altPhone: '',
        city: '',
        address: '',
        unloadingHours: '',
        notes: '',
        priority: 'Media'
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalData = {
      ...formData,
      id: initialData?.id || Math.random().toString(36).substr(2, 9),
      lastContacted: initialData?.lastContacted || new Date().toISOString().split('T')[0]
    } as LogisticsContact;
    onSave(finalData);
  };

  return (
    <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className={`rounded-2xl shadow-2xl w-full max-w-3xl overflow-hidden border transition-all ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
        <div className={`px-8 py-5 border-b flex justify-between items-center ${darkMode ? 'bg-slate-800/50 border-slate-800' : 'bg-slate-50 border-slate-200'}`}>
          <h2 className={`text-xl font-bold ${darkMode ? 'text-white' : 'text-slate-800'}`}>
            {initialData ? 'Editar Registro' : 'Nuevo Registro de Logística'}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors text-2xl">
            &times;
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Cliente</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.client}
                onChange={(e) => setFormData({ ...formData, client: e.target.value })}
                placeholder="Nombre del Cliente Principal"
              />
            </div>
            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Subcliente</label>
              <input
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.subClient}
                onChange={(e) => setFormData({ ...formData, subClient: e.target.value })}
                placeholder="Nombre del Subcliente"
              />
            </div>

            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Contacto Principal</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.contactName}
                onChange={(e) => setFormData({ ...formData, contactName: e.target.value })}
                placeholder="Nombre del Contacto"
              />
            </div>
            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Teléfono Principal</label>
              <input
                required
                type="tel"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              />
            </div>

            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Contacto Alternativo</label>
              <input
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.altContactName}
                onChange={(e) => setFormData({ ...formData, altContactName: e.target.value })}
                placeholder="Nombre Alternativo"
              />
            </div>
            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Teléfono Alternativo</label>
              <input
                type="tel"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.altPhone}
                onChange={(e) => setFormData({ ...formData, altPhone: e.target.value })}
              />
            </div>

            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Ciudad</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.city}
                onChange={(e) => setFormData({ ...formData, city: e.target.value })}
              />
            </div>
            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Prioridad</label>
              <select
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.priority}
                onChange={(e) => setFormData({ ...formData, priority: e.target.value as any })}
              >
                <option value="Baja">Baja</option>
                <option value="Media">Media</option>
                <option value="Alta">Alta</option>
              </select>
            </div>

            <div className="col-span-1 md:col-span-2">
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Dirección Completa</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.address}
                onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                placeholder="Calle, Número, Colonia, C.P."
              />
            </div>

            <div className="col-span-1 md:col-span-2">
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Horarios de Descarga</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
                value={formData.unloadingHours}
                onChange={(e) => setFormData({ ...formData, unloadingHours: e.target.value })}
                placeholder="Ej. Lunes a Viernes 08:00 - 17:00"
              />
            </div>
          </div>
          <div>
            <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>Notas de Operación</label>
            <textarea
              className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
              rows={3}
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              placeholder="Detalles adicionales sobre el sitio o el contacto..."
            />
          </div>
          <div className={`pt-6 flex justify-end gap-4 border-t ${darkMode ? 'border-slate-800' : 'border-slate-200'}`}>
            <button
              type="button"
              onClick={onClose}
              className={`px-6 py-3 rounded-xl font-bold transition-all ${darkMode ? 'text-slate-400 hover:bg-slate-800' : 'text-slate-600 hover:bg-slate-100'}`}
            >
              Cancelar
            </button>
            <button
              type="submit"
              className="px-10 py-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-all shadow-xl shadow-blue-500/20 font-black uppercase tracking-widest text-xs"
            >
              Guardar Registro
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

