              </div>
            </div>

            <div className="grid grid-cols-1 gap-8">
              <div className={`rounded-[2rem] border transition-all overflow-hidden ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100 shadow-sm hover:shadow-xl'}`}>
