                        <div>
                          <p className={`font-bold text-base ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>{c.client}</p>
                          <p className={`text-xs font-medium uppercase tracking-wider ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>{c.contactName} • {c.city}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className={`text-[10px] font-bold ${darkMode ? 'text-slate-600' : 'text-slate-300'}`}>REGISTRADO: {c.lastContacted}</p>
                      </div>
                    </div>
                  ))}
