                          <td className="px-10 py-7">
                            <div className={`text-sm font-bold ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{c.contactName}</div>
                          </td>
                          <td className="px-10 py-7">
                            <div className={`text-sm font-bold ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{c.city}</div>
                            <div className={`text-xs font-medium truncate max-w-xs ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>{c.address}</div>
