                      <div className="flex items-center gap-5">
                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-bold text-sm shadow-inner ${darkMode ? 'bg-[#1a1d23] text-slate-500' : 'bg-slate-100 text-slate-400'}`}>
