                        <th className="px-10 py-6">Cliente / Subcliente</th>
                        <th className="px-10 py-6">Contacto</th>
                        <th className="px-10 py-6">Ciudad / Dirección</th>
                        <th className="px-10 py-6">Teléfonos</th>
                        <th className="px-10 py-6 text-right">Acciones</th>
                      </tr>
                    </thead>
