                            <div className={`font-bold text-lg ${darkMode ? 'text-slate-100' : 'text-slate-800'}`}>{c.client}</div>
                            <div className={`text-xs font-black uppercase tracking-widest ${darkMode ? 'text-slate-500' : 'text-slate-500'}`}>{c.subClient || 'N/A'}</div>
