                    <div className="flex justify-between items-start mb-8">
                      <div className={`w-16 h-16 rounded-2xl flex items-center justify-center font-black text-2xl shadow-inner ${darkMode ? 'bg-blue-500/10 text-blue-500' : 'bg-blue-50 text-blue-600'}`}>
                        {c.client[0]}
                      </div>
                      <div className="flex gap-3">
                        <button 
                          onClick={() => openEditModal(c)}
                          className={`p-3 rounded-xl transition-all ${darkMode ? 'bg-slate-800 text-slate-400 hover:text-blue-400' : 'bg-slate-50 text-slate-400 hover:text-blue-600'}`}
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 1 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                        </button>
                        <button 
                          onClick={() => handleDeleteContact(c.id)}
                          className={`p-3 rounded-xl transition-all ${darkMode ? 'bg-slate-800 text-slate-400 hover:text-rose-400' : 'bg-slate-50 text-slate-400 hover:text-red-500'}`}
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
                        </button>
                      </div>
                    </div>

                    <div className="mb-8">
                      <h4 className={`text-2xl font-black mb-1 leading-tight ${darkMode ? 'text-white' : 'text-slate-900'}`}>{c.client}</h4>
                      <p className={`text-sm font-black uppercase tracking-[0.2em] ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>{c.subClient || 'Sin Subcliente'}</p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
                      <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase tracking-widest text-blue-500">Contactos</label>
                        <div className="space-y-3">
                          <div className="flex flex-col">
                            <span className={`text-sm font-black ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>{c.contactName}</span>
                            <span className={`text-sm font-bold ${darkMode ? 'text-slate-500' : 'text-slate-500'}`}>{c.phone}</span>
                          </div>
                          {c.altContactName && (
                            <div className="flex flex-col border-t border-dashed pt-2 dark:border-slate-800">
                              <span className={`text-xs font-bold ${darkMode ? 'text-slate-400' : 'text-slate-600'}`}>{c.altContactName} (Alt)</span>
                              <span className={`text-xs font-medium ${darkMode ? 'text-slate-500' : 'text-slate-500'}`}>{c.altPhone}</span>
                            </div>
                          )}
                        </div>
                      </div>

                      <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase tracking-widest text-blue-500">Ubicación y Horarios</label>
                        <div className="space-y-3">
                          <a 
                            href={getMapsUrl(c.address, c.city)}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex flex-col group/map"
                            title="Ver en Google Maps"
                          >
                            <span className={`text-sm font-black transition-colors ${darkMode ? 'text-slate-200 group-hover/map:text-blue-400' : 'text-slate-800 group-hover/map:text-blue-600'}`}>{c.city}</span>
                            <span className={`text-xs font-medium leading-relaxed flex items-center gap-1.5 transition-colors ${darkMode ? 'text-slate-500 group-hover/map:text-blue-300' : 'text-slate-500 group-hover/map:text-blue-500'}`}>
                              {c.address}
                              <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="shrink-0 opacity-0 group-hover/map:opacity-100 transition-opacity"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg>
                            </span>
                          </a>
                          <div className="flex items-center gap-2 pt-2">
                            <svg className="text-amber-500" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                            <span className={`text-[11px] font-black ${darkMode ? 'text-slate-400' : 'text-slate-600'}`}>{c.unloadingHours}</span>
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className={`p-5 rounded-2xl mb-8 border border-dashed ${darkMode ? 'bg-slate-800/30 border-slate-700' : 'bg-slate-50 border-slate-200'}`}>
                      <label className="text-[10px] font-black uppercase tracking-widest text-slate-500 block mb-2">Notas Operativas</label>
                      <p className={`text-xs font-medium leading-relaxed italic ${darkMode ? 'text-slate-400' : 'text-slate-600'}`}>{c.notes || 'Sin observaciones registradas.'}</p>
                    </div>

                    <div className="flex justify-between items-center pt-6 border-t dark:border-slate-800">
                      <span className={`text-[9px] font-black uppercase tracking-widest ${darkMode ? 'text-slate-600' : 'text-slate-300'}`}>ACTUALIZADO: {c.lastContacted}</span>
                    </div>
                  </div>
                )) : (
                  <div className="col-span-full py-20 text-center text-slate-500 italic">No hay registros</div>
                )}
              </div>
            )}
          </div>
        )}
      </main>

      <ContactModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveContact}
        initialData={currentContact}
        darkMode={darkMode}
      />
    </div>
  );
};

export default App;

