{
  "name": "Contactos CRM - Gestión Logística",
  "description": "Sistema profesional de gestión de contactos y socios estratégicos para operaciones logísticas de alta eficiencia.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar';
import ContactModal from './components/ContactModal';
import { LogisticsContact } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'agenda'>('dashboard');
  const [viewMode, setViewMode] = useState<'table' | 'grid'>('grid');
  const [contacts, setContacts] = useState<LogisticsContact[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentContact, setCurrentContact] = useState<LogisticsContact | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('logicon_theme');
    return saved === 'dark';
  });

  useEffect(() => {
    const saved = localStorage.getItem('logicon_contacts');
    if (saved) {
      setContacts(JSON.parse(saved));
    } else {
      const mockContacts: LogisticsContact[] = [
        {
          id: '1',
          client: 'Cemex Internacional',
          subClient: 'Planta Monterrey',
          contactName: 'Ing. Alberto Garza',
          phone: '+52 811-234-5678',
          altContactName: 'Lic. Martha Ruiz',
          altPhone: '+52 811-998-7766',
          city: 'Monterrey, NL',
          address: 'Av. Constitución 444, Col. Centro',
          unloadingHours: 'Lun-Vie 07:00 - 18:00',
          notes: 'Requiere equipo de seguridad completo. Entrada por portón B.',
          lastContacted: '2024-05-18'
        }
      ];
      setContacts(mockContacts);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('logicon_contacts', JSON.stringify(contacts));
  }, [contacts]);

  useEffect(() => {
    localStorage.setItem('logicon_theme', darkMode ? 'dark' : 'light');
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const stats = useMemo(() => {
    return {
      total: contacts.length,
    };
  }, [contacts]);

  const filteredContacts = useMemo(() => {
    const s = searchTerm.toLowerCase();
    return contacts.filter(c => 
      c.client.toLowerCase().includes(s) ||
      c.subClient.toLowerCase().includes(s) ||
      c.contactName.toLowerCase().includes(s) ||
      c.city.toLowerCase().includes(s)
    );
  }, [contacts, searchTerm]);

  const handleSaveContact = (contact: LogisticsContact) => {
    if (currentContact) {
      setContacts(prev => prev.map(c => c.id === contact.id ? contact : c));
    } else {
      setContacts(prev => [...prev, contact]);
    }
    setIsModalOpen(false);
    setCurrentContact(null);
  };

  const handleDeleteContact = (id: string) => {
    if (window.confirm('¿Deseas eliminar este registro permanentemente?')) {
      setContacts(prev => prev.filter(c => c.id !== id));
    }
  };

  const openEditModal = (contact: LogisticsContact) => {
    setCurrentContact(contact);
    setIsModalOpen(true);
  };

  const toggleTheme = () => setDarkMode(!darkMode);

  const getMapsUrl = (address: string, city: string) => {
    return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${address}, ${city}`)}`;
  };

  const exportToJSON = () => {
    const dataStr = JSON.stringify(contacts, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
    const exportFileDefaultName = `agenda_logistica_${new Date().toISOString().split('T')[0]}.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  const exportToCSV = () => {
    const headers = ['Cliente', 'Subcliente', 'Contacto', 'Teléfono', 'Contacto Alt', 'Teléfono Alt', 'Ciudad', 'Dirección', 'Horarios', 'Notas'];
    const rows = contacts.map(c => [
      `"${c.client}"`,
      `"${c.subClient}"`,
      `"${c.contactName}"`,
      `"${c.phone}"`,
      `"${c.altContactName}"`,
      `"${c.altPhone}"`,
      `"${c.city}"`,
      `"${c.address}"`,
      `"${c.unloadingHours}"`,
      `"${c.notes}"`
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n" 
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `agenda_logistica_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        if (Array.isArray(json)) {
          if (window.confirm('¿Deseas reemplazar los datos actuales con los del archivo importado?')) {
            setContacts(json);
          }
        } else {
          alert('El archivo no tiene el formato correcto.');
        }
      } catch (err) {
        alert('Error al leer el archivo. Asegúrate de que sea un JSON válido.');
      }
    };
    reader.readAsText(file);
    event.target.value = ''; // Reset input
  };

  return (
    <div className={`flex min-h-screen transition-all duration-500 ease-in-out ${darkMode ? 'bg-[#0f1008] text-amber-50' : 'bg-amber-50/30 text-slate-900'}`}>
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        darkMode={darkMode} 
        onExportJSON={exportToJSON}
        onExportCSV={exportToCSV}
        onImport={handleImportClick}
      />
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept=".json" 
        onChange={handleFileImport} 
      />

      <main className="flex-1 ml-64 p-8 lg:p-12">
        <header className="flex justify-between items-center mb-12">
          <div>
            <h2 className={`text-4xl font-extrabold tracking-tight ${darkMode ? 'text-amber-400' : 'text-amber-900'}`}>
              {activeTab === 'dashboard' && 'Visión General'}
              {activeTab === 'agenda' && 'Directorio Logístico'}
            </h2>
            <div className="flex items-center gap-2 mt-1">
              <span className={`w-2 h-2 rounded-full bg-amber-500 animate-pulse`}></span>
              <p className={`text-sm font-medium ${darkMode ? 'text-amber-500/60' : 'text-amber-700/60'}`}>
                Gestión de contactos
              </p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button 
              onClick={toggleTheme}
              className={`p-3 rounded-2xl transition-all duration-300 border ${darkMode ? 'bg-amber-950/20 border-amber-800 text-amber-400 hover:border-amber-400/50' : 'bg-white border-amber-200 text-amber-600 shadow-sm hover:border-amber-400'}`}
              title="Cambiar Tema"
            >
              {darkMode ? (
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>
              )}
            </button>
            <button 
              onClick={() => { setCurrentContact(null); setIsModalOpen(true); }}
              className="bg-amber-600 hover:bg-amber-700 text-white px-8 py-3.5 rounded-2xl shadow-xl shadow-amber-500/20 font-bold transition-all flex items-center gap-3 transform hover:-translate-y-1 active:scale-95"
