                      <p className={`text-sm font-black uppercase tracking-[0.2em] ${darkMode ? 'text-amber-700' : 'text-amber-600/60'}`}>{c.subClient || 'Sin Subcliente'}</p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
                      <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase tracking-widest text-amber-500">Contactos</label>
                        <div className="space-y-3">
                          <div className="flex flex-col">
                            <span className={`text-sm font-black ${darkMode ? 'text-amber-200' : 'text-amber-800'}`}>{c.contactName}</span>
                            <span className={`text-sm font-bold ${darkMode ? 'text-amber-700' : 'text-amber-600/70'}`}>{c.phone}</span>
                          </div>
                          {c.altContactName && (
                            <div className="flex flex-col border-t border-dashed pt-2 dark:border-amber-900/30">
                              <span className={`text-xs font-bold ${darkMode ? 'text-amber-500' : 'text-amber-700'}`}>{c.altContactName} (Alt)</span>
                              <span className={`text-xs font-medium ${darkMode ? 'text-amber-700' : 'text-amber-600/70'}`}>{c.altPhone}</span>
                            </div>
                          )}
                        </div>
                      </div>

                      <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase tracking-widest text-amber-500">Ubicación y Horarios</label>
                        <div className="space-y-3">
                          <a 
                            href={getMapsUrl(c.address, c.city)}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex flex-col group/map"
                            title="Ver en Google Maps"
                          >
                            <span className={`text-sm font-black transition-colors ${darkMode ? 'text-amber-200 group-hover/map:text-amber-400' : 'text-amber-900 group-hover/map:text-amber-600'}`}>{c.city}</span>
                            <span className={`text-xs font-medium leading-relaxed flex items-center gap-1.5 transition-colors ${darkMode ? 'text-amber-700 group-hover/map:text-amber-300' : 'text-amber-600 group-hover/map:text-amber-500'}`}>
                              {c.address}
                              <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="shrink-0 opacity-0 group-hover/map:opacity-100 transition-opacity"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg>
                            </span>
                          </a>
                          <div className="flex items-center gap-2 pt-2">
                            <svg className="text-amber-500" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                            <span className={`text-[11px] font-black ${darkMode ? 'text-amber-600' : 'text-amber-700'}`}>{c.unloadingHours}</span>
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className={`p-5 rounded-2xl mb-8 border border-dashed ${darkMode ? 'bg-amber-950/20 border-amber-900/50' : 'bg-amber-50/50 border-amber-200'}`}>
                      <label className="text-[10px] font-black uppercase tracking-widest text-amber-700 block mb-2">Notas Operativas</label>
                      <p className={`text-xs font-medium leading-relaxed italic ${darkMode ? 'text-amber-400/80' : 'text-amber-800/80'}`}>{c.notes || 'Sin observaciones registradas.'}</p>
                    </div>

                    <div className="flex justify-between items-center pt-6 border-t dark:border-amber-900/30">
                      <span className={`text-[9px] font-black uppercase tracking-widest ${darkMode ? 'text-amber-900' : 'text-amber-200'}`}>ACTUALIZADO: {c.lastContacted}</span>
                    </div>
                  </div>
                )) : (
                  <div className="col-span-full py-20 text-center text-amber-700 italic">No hay registros</div>
                )}
              </div>
            )}
          </div>
        )}
      </main>

      <ContactModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveContact}
        initialData={currentContact}
        darkMode={darkMode}
      />
    </div>
  );
};

export default App;

