import React, { useState, useEffect } from 'react';
import { LogisticsContact } from '../types';

interface ContactModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (contact: LogisticsContact) => void;
  initialData?: LogisticsContact | null;
  darkMode?: boolean;
}

const ContactModal: React.FC<ContactModalProps> = ({ isOpen, onClose, onSave, initialData, darkMode }) => {
  const [formData, setFormData] = useState<Partial<LogisticsContact>>({
    client: '',
    subClient: '',
    contactName: '',
    phone: '',
    altContactName: '',
    altPhone: '',
    city: '',
    address: '',
    unloadingHours: '',
    notes: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        client: '',
        subClient: '',
        contactName: '',
        phone: '',
        altContactName: '',
        altPhone: '',
        city: '',
        address: '',
        unloadingHours: '',
        notes: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalData = {
      ...formData,
      id: initialData?.id || Math.random().toString(36).substr(2, 9),
      lastContacted: initialData?.lastContacted || new Date().toISOString().split('T')[0]
    } as LogisticsContact;
    onSave(finalData);
  };

  return (
    <div className="fixed inset-0 bg-amber-950/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className={`rounded-2xl shadow-2xl w-full max-w-3xl overflow-hidden border transition-all ${darkMode ? 'bg-[#0f1008] border-amber-900/50' : 'bg-white border-amber-200'}`}>
        <div className={`px-8 py-5 border-b flex justify-between items-center ${darkMode ? 'bg-amber-950/20 border-amber-900/50' : 'bg-amber-50 border-amber-200'}`}>
          <h2 className={`text-xl font-bold ${darkMode ? 'text-amber-400' : 'text-amber-900'}`}>
            {initialData ? 'Editar Registro' : 'Nuevo Registro de Logística'}
          </h2>
          <button onClick={onClose} className="text-amber-700 hover:text-amber-500 transition-colors text-2xl">
            &times;
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-amber-700' : 'text-amber-600'}`}>Cliente</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-500 outline-none transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/30 text-amber-100 placeholder-amber-900' : 'bg-white border-amber-200 text-amber-900'}`}
                value={formData.client}
                onChange={(e) => setFormData({ ...formData, client: e.target.value })}
                placeholder="Nombre del Cliente Principal"
              />
            </div>
            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-amber-700' : 'text-amber-600'}`}>Subcliente</label>
              <input
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-500 outline-none transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/30 text-amber-100 placeholder-amber-900' : 'bg-white border-amber-200 text-amber-900'}`}
                value={formData.subClient}
                onChange={(e) => setFormData({ ...formData, subClient: e.target.value })}
                placeholder="Nombre del Subcliente"
              />
            </div>

            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-amber-700' : 'text-amber-600'}`}>Contacto Principal</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-500 outline-none transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/30 text-amber-100 placeholder-amber-900' : 'bg-white border-amber-200 text-amber-900'}`}
                value={formData.contactName}
                onChange={(e) => setFormData({ ...formData, contactName: e.target.value })}
                placeholder="Nombre del Contacto"
              />
            </div>
            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-amber-700' : 'text-amber-600'}`}>Teléfono Principal</label>
              <input
                required
                type="tel"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-500 outline-none transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/30 text-amber-100 placeholder-amber-900' : 'bg-white border-amber-200 text-amber-900'}`}
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              />
            </div>

            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-amber-700' : 'text-amber-600'}`}>Contacto Alternativo</label>
              <input
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-500 outline-none transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/30 text-amber-100 placeholder-amber-900' : 'bg-white border-amber-200 text-amber-900'}`}
                value={formData.altContactName}
                onChange={(e) => setFormData({ ...formData, altContactName: e.target.value })}
                placeholder="Nombre Alternativo"
              />
            </div>
            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-amber-700' : 'text-amber-600'}`}>Teléfono Alternativo</label>
              <input
                type="tel"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-500 outline-none transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/30 text-amber-100 placeholder-amber-900' : 'bg-white border-amber-200 text-amber-900'}`}
                value={formData.altPhone}
                onChange={(e) => setFormData({ ...formData, altPhone: e.target.value })}
              />
            </div>

            <div>
              <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-amber-700' : 'text-amber-600'}`}>Ciudad</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-500 outline-none transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/30 text-amber-100 placeholder-amber-900' : 'bg-white border-amber-200 text-amber-900'}`}
                value={formData.city}
                onChange={(e) => setFormData({ ...formData, city: e.target.value })}
              />
            </div>

