              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-500 outline-none transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/30 text-amber-100 placeholder-amber-900' : 'bg-white border-amber-200 text-amber-900'}`}
                value={formData.unloadingHours}
