          <div>
            <label className={`block text-xs font-black uppercase tracking-widest mb-2 ${darkMode ? 'text-amber-700' : 'text-amber-600'}`}>Notas de Operación</label>
            <textarea
              className={`w-full border rounded-xl px-4 py-3 focus:ring-2 focus:ring-amber-500 outline-none transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/30 text-amber-100 placeholder-amber-900' : 'bg-white border-amber-200 text-amber-900'}`}
              rows={3}
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              placeholder="Detalles adicionales sobre el sitio o el contacto..."
            />
          </div>
          <div className={`pt-6 flex justify-end gap-4 border-t ${darkMode ? 'border-amber-900/30' : 'border-amber-200'}`}>
            <button
              type="button"
              onClick={onClose}
              className={`px-6 py-3 rounded-xl font-bold transition-all ${darkMode ? 'text-amber-700 hover:bg-amber-950/30' : 'text-amber-700 hover:bg-amber-50'}`}
            >
              Cancelar
            </button>
            <button
              type="submit"
              className="px-10 py-3 bg-amber-600 text-white rounded-xl hover:bg-amber-700 transition-all shadow-xl shadow-amber-500/20 font-black uppercase tracking-widest text-xs"
            >
              Guardar Registro
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

