              Nuevo Registro
            </button>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="space-y-10 animate-in fade-in slide-in-from-top-4 duration-700">
            <div className="flex max-w-sm">
              <div className={`w-full p-8 rounded-[2rem] border transition-all ${darkMode ? 'bg-amber-950/10 border-amber-900/50' : 'bg-white border-amber-100 shadow-sm hover:shadow-xl'}`}>
                <div className="flex justify-between items-center mb-6">
                  <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${darkMode ? 'text-amber-700' : 'text-amber-600'}`}>Almacenes / Destinos</span>
                  <div className="p-3 bg-amber-500/10 text-amber-500 rounded-xl">
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 21h18"/><path d="M3 7v1a3 3 0 0 0 6 0V7"/><path d="M9 7v1a3 3 0 0 0 6 0V7"/><path d="M15 7v1a3 3 0 0 0 6 0V7"/><path d="M19 21v-8a2 2 0 0 0-2-2H7a2 2 0 0 0-2 2v8"/><rect width="4" height="6" x="10" y="15"/></svg>
                  </div>
                </div>
                <p className={`text-5xl font-black mb-1 ${darkMode ? 'text-amber-400' : 'text-amber-900'}`}>{stats.total}</p>
