            </div>

            <div className="grid grid-cols-1 gap-8">
              <div className={`rounded-[2rem] border transition-all overflow-hidden ${darkMode ? 'bg-amber-950/10 border-amber-900/50' : 'bg-white border-amber-100 shadow-sm hover:shadow-xl'}`}>
                <div className={`p-8 border-b flex justify-between items-center ${darkMode ? 'border-amber-900/50' : 'border-amber-50'}`}>
                  <h3 className={`text-lg font-bold ${darkMode ? 'text-amber-400' : 'text-amber-900'}`}>Cargas y Movimientos Recientes</h3>
