                </div>
                <div className={`divide-y ${darkMode ? 'divide-amber-900/30' : 'divide-amber-50'}`}>
                  {contacts.slice(-5).reverse().map((c) => (
                    <div key={c.id} className={`p-6 flex items-center justify-between transition-colors ${darkMode ? 'hover:bg-amber-950/20' : 'hover:bg-amber-50/50'}`}>
                      <div className="flex items-center gap-5">
