                          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M10 17h4V2H10v15z"/><path d="M22 17v1a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2v-1"/><path d="M12 22v-5"/><path d="M5 17h14"/></svg>
                        </div>
                        <div>
                          <p className={`font-bold text-base ${darkMode ? 'text-amber-200' : 'text-amber-900'}`}>{c.client}</p>
