import React, { useState, useEffect } from 'react';
import { LogisticsContact } from '../types';

interface ContactModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (contact: LogisticsContact) => void;
  initialData?: LogisticsContact | null;
  darkMode?: boolean;
}

const ContactModal: React.FC<ContactModalProps> = ({ isOpen, onClose, onSave, initialData, darkMode }) => {
  const [formData, setFormData] = useState<Partial<LogisticsContact>>({
    client: '',
    subClient: '',
    contactName: '',
    phone: '',
    altContactName: '',
    altPhone: '',
    city: '',
    address: '',
    unloadingHours: '',
    notes: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        client: '',
        subClient: '',
        contactName: '',
        phone: '',
        altContactName: '',
        altPhone: '',
        city: '',
        address: '',
        unloadingHours: '',
        notes: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalData = {
      ...formData,
      id: initialData?.id || Math.random().toString(36).substr(2, 9),
      lastContacted: initialData?.lastContacted || new Date().toISOString().split('T')[0]
    } as LogisticsContact;
    onSave(finalData);
  };

  return (
    <div className="fixed inset-0 bg-stone-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className={`rounded-3xl shadow-2xl w-full max-w-3xl overflow-hidden border transition-all ${darkMode ? 'bg-[#1a1a18] border-stone-800' : 'bg-white border-stone-100'}`}>
        <div className={`px-8 py-6 border-b flex justify-between items-center ${darkMode ? 'bg-stone-900/20 border-stone-800/50' : 'bg-stone-50/50 border-stone-100'}`}>
          <h2 className={`text-xl font-bold ${darkMode ? 'text-[#c2a265]' : 'text-stone-800'}`}>
            {initialData ? 'Editar Registro' : 'Nuevo Registro Operativo'}
          </h2>
          <button onClick={onClose} className={`text-2xl transition-colors ${darkMode ? 'text-stone-700 hover:text-[#c2a265]' : 'text-stone-300 hover:text-stone-800'}`}>
            &times;
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className={`block text-[10px] font-bold uppercase tracking-widest mb-2 ${darkMode ? 'text-stone-600' : 'text-stone-400'}`}>Cliente Principal</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3.5 outline-none transition-all font-medium ${darkMode ? 'bg-[#141412] border-stone-800 text-stone-200 placeholder-stone-800 focus:border-[#c2a265]/50' : 'bg-stone-50 border-stone-100 text-stone-800 focus:border-stone-200'}`}
                value={formData.client}
                onChange={(e) => setFormData({ ...formData, client: e.target.value })}
                placeholder="Nombre de la empresa"
              />
            </div>
            <div>
              <label className={`block text-[10px] font-bold uppercase tracking-widest mb-2 ${darkMode ? 'text-stone-600' : 'text-stone-400'}`}>Subcliente / Planta</label>
              <input
                type="text"
                className={`w-full border rounded-xl px-4 py-3.5 outline-none transition-all font-medium ${darkMode ? 'bg-[#141412] border-stone-800 text-stone-200 placeholder-stone-800 focus:border-[#c2a265]/50' : 'bg-stone-50 border-stone-100 text-stone-800 focus:border-stone-200'}`}
                value={formData.subClient}
                onChange={(e) => setFormData({ ...formData, subClient: e.target.value })}
                placeholder="Especifique ubicación o filial"
              />
            </div>

            <div>
              <label className={`block text-[10px] font-bold uppercase tracking-widest mb-2 ${darkMode ? 'text-stone-600' : 'text-stone-400'}`}>Responsable de Sitio</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3.5 outline-none transition-all font-medium ${darkMode ? 'bg-[#141412] border-stone-800 text-stone-200 placeholder-stone-800 focus:border-[#c2a265]/50' : 'bg-stone-50 border-stone-100 text-stone-800 focus:border-stone-200'}`}
                value={formData.contactName}
                onChange={(e) => setFormData({ ...formData, contactName: e.target.value })}
                placeholder="Nombre completo"
              />
            </div>
            <div>
              <label className={`block text-[10px] font-bold uppercase tracking-widest mb-2 ${darkMode ? 'text-stone-600' : 'text-stone-400'}`}>Teléfono de Contacto</label>
              <input
                required
                type="tel"
                className={`w-full border rounded-xl px-4 py-3.5 outline-none transition-all font-medium ${darkMode ? 'bg-[#141412] border-stone-800 text-stone-200 placeholder-stone-800 focus:border-[#c2a265]/50' : 'bg-stone-50 border-stone-100 text-stone-800 focus:border-stone-200'}`}
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              />
            </div>

            <div>
              <label className={`block text-[10px] font-bold uppercase tracking-widest mb-2 ${darkMode ? 'text-stone-600' : 'text-stone-400'}`}>Ciudad / Localidad</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3.5 outline-none transition-all font-medium ${darkMode ? 'bg-[#141412] border-stone-800 text-stone-200 placeholder-stone-800 focus:border-[#c2a265]/50' : 'bg-stone-50 border-stone-100 text-stone-800 focus:border-stone-200'}`}
                value={formData.city}
                onChange={(e) => setFormData({ ...formData, city: e.target.value })}
              />
            </div>

            <div>
              <label className={`block text-[10px] font-bold uppercase tracking-widest mb-2 ${darkMode ? 'text-stone-600' : 'text-stone-400'}`}>Horarios de Descarga</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3.5 outline-none transition-all font-medium ${darkMode ? 'bg-[#141412] border-stone-800 text-stone-200 placeholder-stone-800 focus:border-[#c2a265]/50' : 'bg-stone-50 border-stone-100 text-stone-800 focus:border-stone-200'}`}
                value={formData.unloadingHours}
                onChange={(e) => setFormData({ ...formData, unloadingHours: e.target.value })}
                placeholder="Ej. Lun-Vie 07:00 a 18:00"
              />
            </div>

            <div className="col-span-1 md:col-span-2">
              <label className={`block text-[10px] font-bold uppercase tracking-widest mb-2 ${darkMode ? 'text-stone-600' : 'text-stone-400'}`}>Dirección Detallada</label>
              <input
                required
                type="text"
                className={`w-full border rounded-xl px-4 py-3.5 outline-none transition-all font-medium ${darkMode ? 'bg-[#141412] border-stone-800 text-stone-200 placeholder-stone-800 focus:border-[#c2a265]/50' : 'bg-stone-50 border-stone-100 text-stone-800 focus:border-stone-200'}`}
                value={formData.address}
                onChange={(e) => setFormData({ ...formData, address: e.target.value })}
              />
            </div>
          </div>

          <div>
            <label className={`block text-[10px] font-bold uppercase tracking-widest mb-2 ${darkMode ? 'text-stone-600' : 'text-stone-400'}`}>Notas de Operación</label>
            <textarea
              className={`w-full border rounded-xl px-4 py-3.5 outline-none transition-all font-medium resize-none ${darkMode ? 'bg-[#141412] border-stone-800 text-stone-200 placeholder-stone-800 focus:border-[#c2a265]/50' : 'bg-stone-50 border-stone-100 text-stone-800 focus:border-stone-200'}`}
              rows={3}
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              placeholder="Indicaciones especiales, acceso, etc."
            />
          </div>

          <div className={`pt-8 flex justify-end gap-4 border-t ${darkMode ? 'border-stone-800/50' : 'border-stone-100'}`}>
            <button
              type="button"
              onClick={onClose}
              className={`px-6 py-3 rounded-2xl font-bold transition-all ${darkMode ? 'text-stone-600 hover:text-stone-300' : 'text-stone-400 hover:text-stone-800'}`}
            >
              Cerrar
            </button>
            <button
              type="submit"
              className={`px-10 py-3.5 rounded-2xl font-bold uppercase tracking-widest text-xs transition-all shadow-lg ${darkMode ? 'bg-[#c2a265] text-stone-900 hover:bg-[#d4b982]' : 'bg-[#8c734b] text-white hover:bg-[#7a6441]'}`}
            >
              Confirmar Datos
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ContactModal;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar';
import ContactModal from './components/ContactModal';
import { LogisticsContact } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'agenda'>('dashboard');
  const [viewMode, setViewMode] = useState<'table' | 'grid'>('grid');
  const [contacts, setContacts] = useState<LogisticsContact[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentContact, setCurrentContact] = useState<LogisticsContact | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('logicon_theme');
    return saved === 'dark';
  });

  useEffect(() => {
    const saved = localStorage.getItem('logicon_contacts');
    if (saved) {
      setContacts(JSON.parse(saved));
    } else {
      const mockContacts: LogisticsContact[] = [
        {
          id: '1',
          client: 'Cemex Internacional',
          subClient: 'Planta Monterrey',
          contactName: 'Ing. Alberto Garza',
          phone: '+52 811-234-5678',
          altContactName: 'Lic. Martha Ruiz',
          altPhone: '+52 811-998-7766',
          city: 'Monterrey, NL',
          address: 'Av. Constitución 444, Col. Centro',
          unloadingHours: 'Lun-Vie 07:00 - 18:00',
          notes: 'Requiere equipo de seguridad completo. Entrada por portón B.',
          lastContacted: '2024-05-18'
        }
      ];
      setContacts(mockContacts);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('logicon_contacts', JSON.stringify(contacts));
  }, [contacts]);

  useEffect(() => {
    localStorage.setItem('logicon_theme', darkMode ? 'dark' : 'light');
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const stats = useMemo(() => {
    return {
      total: contacts.length,
    };
  }, [contacts]);

  const filteredContacts = useMemo(() => {
    const s = searchTerm.toLowerCase();
    return contacts.filter(c => 
      c.client.toLowerCase().includes(s) ||
      c.subClient.toLowerCase().includes(s) ||
      c.contactName.toLowerCase().includes(s) ||
      c.city.toLowerCase().includes(s)
    );
  }, [contacts, searchTerm]);

  const handleSaveContact = (contact: LogisticsContact) => {
    if (currentContact) {
      setContacts(prev => prev.map(c => c.id === contact.id ? contact : c));
    } else {
      setContacts(prev => [...prev, contact]);
    }
    setIsModalOpen(false);
    setCurrentContact(null);
  };

  const handleDeleteContact = (id: string) => {
    if (window.confirm('¿Deseas eliminar este registro permanentemente?')) {
      setContacts(prev => prev.filter(c => c.id !== id));
    }
  };

  const openEditModal = (contact: LogisticsContact) => {
    setCurrentContact(contact);
    setIsModalOpen(true);
  };

  const toggleTheme = () => setDarkMode(!darkMode);

  const getMapsUrl = (address: string, city: string) => {
    return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${address}, ${city}`)}`;
  };

  const exportToJSON = () => {
    const dataStr = JSON.stringify(contacts, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
    const exportFileDefaultName = `agenda_logistica_${new Date().toISOString().split('T')[0]}.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  const exportToCSV = () => {
    const headers = ['Cliente', 'Subcliente', 'Contacto', 'Teléfono', 'Contacto Alt', 'Teléfono Alt', 'Ciudad', 'Dirección', 'Horarios', 'Notas'];
    const rows = contacts.map(c => [
      `"${c.client}"`,
      `"${c.subClient}"`,
      `"${c.contactName}"`,
      `"${c.phone}"`,
      `"${c.altContactName}"`,
      `"${c.altPhone}"`,
      `"${c.city}"`,
      `"${c.address}"`,
      `"${c.unloadingHours}"`,
      `"${c.notes}"`
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n" 
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `agenda_logistica_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        if (Array.isArray(json)) {
          if (window.confirm('¿Deseas reemplazar los datos actuales con los del archivo importado?')) {
            setContacts(json);
          }
        } else {
          alert('El archivo no tiene el formato correcto.');
        }
      } catch (err) {
        alert('Error al leer el archivo. Asegúrate de que sea un JSON válido.');
      }
    };
    reader.readAsText(file);
    event.target.value = ''; // Reset input
  };

  return (
    <div className={`flex min-h-screen transition-all duration-500 ease-in-out ${darkMode ? 'bg-[#0f1412] text-[#e0e7e5]' : 'bg-[#f7faf9] text-[#242b29]'}`}>
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        darkMode={darkMode} 
        onExportJSON={exportToJSON}
        onExportCSV={exportToCSV}
        onImport={handleImportClick}
      />
      <input 
        type="file" 
        ref={fileInputRef} 
        className="hidden" 
        accept=".json" 
        onChange={handleFileImport} 
      />

      <main className="flex-1 ml-64 p-8 lg:p-12">
        <header className="flex justify-between items-center mb-12">
          <div>
            <h2 className={`text-4xl font-bold tracking-tight ${darkMode ? 'text-emerald-400' : 'text-emerald-800'}`}>
              {activeTab === 'dashboard' && 'Visión General'}
              {activeTab === 'agenda' && 'Directorio de Operaciones'}
            </h2>
            <div className="flex items-center gap-2 mt-2">
              <span className={`w-2 h-2 rounded-full bg-emerald-500 opacity-50`}></span>
              <p className={`text-sm font-medium ${darkMode ? 'text-stone-500' : 'text-stone-400'}`}>
                Control de Red Tucumán
              </p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button 
              onClick={toggleTheme}
              className={`p-3 rounded-2xl transition-all duration-300 border ${darkMode ? 'bg-[#1a221f] border-emerald-900/30 text-emerald-500 hover:border-emerald-500/50 hover:text-emerald-400' : 'bg-white border-emerald-100 text-emerald-600 shadow-sm hover:border-emerald-300'}`}
              title="Cambiar Tema"
            >
              {darkMode ? (
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>
              )}
            </button>
            <button 
              onClick={() => { setCurrentContact(null); setIsModalOpen(true); }}
              className={`px-8 py-3.5 rounded-2xl shadow-lg font-bold transition-all flex items-center gap-3 transform hover:-translate-y-0.5 active:scale-95 ${darkMode ? 'bg-emerald-500 text-emerald-950 hover:bg-emerald-400' : 'bg-emerald-700 text-white hover:bg-emerald-800'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14"/><path d="M12 5v14"/></svg>
              Nuevo Registro
            </button>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="space-y-10 animate-in fade-in duration-700">
