      setFormData({
        client: '',
        subClient: '',
        contactName: '',
        phone: '',
        altContactName: '',
        altPhone: '',
        city: '',
        address: '',
        unloadingHours: '',
        notes: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

