                        </button>
                        <button onClick={() => handleDeleteContact(c.id)} className={`p-2 rounded-lg ${darkMode ? 'text-slate-600 hover:text-rose-500 hover:bg-slate-950' : 'text-slate-300 hover:text-rose-600 hover:bg-slate-50'}`}>
                          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
                        </button>
                      </div>
                    </div>
                    <div className="mb-6">
                      <h4 className={`text-lg font-bold mb-1 ${darkMode ? 'text-white' : 'text-slate-900'}`}>{c.client}</h4>
                      <p className={`text-[10px] font-bold uppercase tracking-widest ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>{c.subClient || 'Sin filial'}</p>
                    </div>
                    <div className="grid grid-cols-2 gap-6 mb-6">
                      <div>
                        <p className={`text-[10px] font-bold uppercase text-emerald-600 mb-1`}>Contacto</p>
                        <p className={`text-xs font-bold ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{c.contactName}</p>
                        <p className={`text-[11px] font-medium text-slate-500`}>{c.phone}</p>
                      </div>
                      <div>
                        <p className={`text-[10px] font-bold uppercase text-emerald-600 mb-1`}>Ubicación</p>
                        <p className={`text-xs font-bold ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{c.city}</p>
                        <a href={getMapsUrl(c.address, c.city)} target="_blank" className={`text-[11px] font-medium text-slate-500 hover:text-emerald-500 flex items-center gap-1 mt-0.5`}>
                          Mapa <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/></svg>
                        </a>
                      </div>
                    </div>
                    <div className={`p-4 rounded-xl text-[11px] leading-relaxed italic border border-dashed ${darkMode ? 'bg-slate-950/50 border-slate-800 text-slate-500' : 'bg-slate-50 border-slate-200 text-slate-500'}`}>
                      {c.notes || 'Sin especificaciones.'}
                    </div>
                  </div>
                )) : (
                  <div className="col-span-full py-20 text-center text-slate-500 italic">No se encontraron resultados</div>
                )}
              </div>
            )}
          </div>
        )}
      </main>

      <ContactModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveContact}
        initialData={currentContact}
        darkMode={darkMode}
      />
    </div>
  );
};

export default App;

