import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar';
import ContactModal from './components/ContactModal';
import { LogisticsContact } from './types';

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<'table' | 'grid'>('grid');
  const [contacts, setContacts] = useState<LogisticsContact[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentContact, setCurrentContact] = useState<LogisticsContact | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('logicon_theme');
    return saved === 'dark';
  });

  useEffect(() => {
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });

    const saved = localStorage.getItem('logicon_contacts');
    if (saved) {
      setContacts(JSON.parse(saved));
    } else {
      const mockContacts: LogisticsContact[] = [
        {
          id: '1',
          client: 'Cemex Internacional',
          subClient: 'Planta Monterrey',
          contactName: 'Ing. Alberto Garza',
          phone: '+52 811-234-5678',
          altContactName: 'Lic. Martha Ruiz',
          altPhone: '+52 811-998-7766',
          city: 'Monterrey, NL',
          address: 'Av. Constitución 444, Col. Centro',
          unloadingHours: 'Lun-Vie 07:00 - 18:00',
          notes: 'Requiere equipo de seguridad completo. Entrada por portón B.',
          lastContacted: '2024-05-18'
        }
      ];
      setContacts(mockContacts);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('logicon_contacts', JSON.stringify(contacts));
  }, [contacts]);

  useEffect(() => {
    localStorage.setItem('logicon_theme', darkMode ? 'dark' : 'light');
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const handleInstallApp = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        setDeferredPrompt(null);
      }
    }
  };

  const filteredContacts = useMemo(() => {
    const s = searchTerm.toLowerCase();
    return contacts.filter(c => 
      c.client.toLowerCase().includes(s) ||
      c.subClient.toLowerCase().includes(s) ||
      c.contactName.toLowerCase().includes(s) ||
      c.city.toLowerCase().includes(s)
    );
  }, [contacts, searchTerm]);

  const handleSaveContact = (contact: LogisticsContact) => {
    if (currentContact) {
      setContacts(prev => prev.map(c => c.id === contact.id ? contact : c));
    } else {
      setContacts(prev => [...prev, contact]);
    }
    setIsModalOpen(false);
    setCurrentContact(null);
  };

  const handleDeleteContact = (id: string) => {
    if (window.confirm('¿Deseas eliminar este registro permanentemente?')) {
      setContacts(prev => prev.filter(c => c.id !== id));
    }
  };

  const openEditModal = (contact: LogisticsContact) => {
    setCurrentContact(contact);
    setIsModalOpen(true);
  };

  const toggleTheme = () => setDarkMode(!darkMode);

  const getMapsUrl = (address: string, city: string) => {
    return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${address}, ${city}`)}`;
  };

  const exportToJSON = () => {
    const dataStr = JSON.stringify(contacts, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', `agenda_logistica_${new Date().toISOString().split('T')[0]}.json`);
    linkElement.click();
  };

  const exportToCSV = () => {
    const headers = ['Cliente', 'Subcliente', 'Contacto', 'Teléfono', 'Contacto Alt', 'Teléfono Alt', 'Ciudad', 'Dirección', 'Horarios', 'Notas'];
    const rows = contacts.map(c => [`"${c.client}"`, `"${c.subClient}"`, `"${c.contactName}"`, `"${c.phone}"`, `"${c.altContactName}"`, `"${c.altPhone}"`, `"${c.city}"`, `"${c.address}"`, `"${c.unloadingHours}"`, `"${c.notes}"`]);
    const csvContent = "data:text/csv;charset=utf-8," + headers.join(",") + "\n" + rows.map(e => e.join(",")).join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", `agenda_logistica_${new Date().toISOString().split('T')[0]}.csv`);
    link.click();
  };

  const handleImportClick = () => fileInputRef.current?.click();

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        if (Array.isArray(json) && window.confirm('¿Deseas reemplazar los datos actuales con los del archivo?')) {
          setContacts(json);
        }
      } catch (err) { alert('Archivo inválido.'); }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  return (
    <div className={`flex min-h-screen transition-all duration-500 ease-in-out ${darkMode ? 'bg-[#0f1110] text-slate-200' : 'bg-slate-50 text-slate-900'}`}>
      <Sidebar 
        darkMode={darkMode} 
        onExportJSON={exportToJSON}
        onExportCSV={exportToCSV}
        onImport={handleImportClick}
        showInstall={!!deferredPrompt}
        onInstall={handleInstallApp}
      />
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleFileImport} />

      <main className="flex-1 ml-64 p-8 lg:p-12">
        <header className="flex justify-between items-center mb-12">
          <div>
            <h2 className={`text-3xl font-bold tracking-tight ${darkMode ? 'text-white' : 'text-slate-900'}`}>
              Directorio Operativo
            </h2>
            <div className="flex items-center gap-2 mt-2">
              <span className={`w-2 h-2 rounded-full bg-emerald-500`}></span>
              <p className={`text-sm font-medium ${darkMode ? 'text-slate-500' : 'text-slate-400'}`}>
                Control de Red Tucumán
              </p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <button 
              onClick={toggleTheme}
              className={`p-2.5 rounded-xl transition-all border ${darkMode ? 'bg-slate-900 border-slate-800 text-slate-400 hover:text-emerald-400' : 'bg-white border-slate-200 text-slate-500 shadow-sm hover:border-slate-300'}`}
              title="Cambiar Tema"
            >
              {darkMode ? (
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>
              )}
            </button>
            <button 
              onClick={() => { setCurrentContact(null); setIsModalOpen(true); }}
              className={`px-6 py-3 rounded-xl shadow-lg font-bold transition-all flex items-center gap-2 transform hover:-translate-y-0.5 active:scale-95 ${darkMode ? 'bg-emerald-600 text-white hover:bg-emerald-500' : 'bg-emerald-700 text-white hover:bg-emerald-800'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14"/><path d="M12 5v14"/></svg>
              Nuevo Registro
            </button>
          </div>
        </header>

        <div className="space-y-6 animate-in slide-in-from-bottom-2 duration-500">
          <div className={`p-6 rounded-2xl border ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200 shadow-sm'}`}>
            <div className="flex flex-col md:flex-row gap-4 justify-between items-center">
              <div className="relative w-full md:w-80 group">
                <span className={`absolute left-4 top-1/2 -translate-y-1/2 ${darkMode ? 'text-slate-600 group-focus-within:text-emerald-500' : 'text-slate-300 group-focus-within:text-emerald-600'}`}>
                  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
                </span>
                <input 
                  type="text"
                  placeholder="Buscar contacto..."
                  className={`w-full pl-11 pr-4 py-2.5 border rounded-xl outline-none transition-all text-sm font-medium ${darkMode ? 'bg-slate-950 border-slate-800 text-slate-200 placeholder-slate-700 focus:border-emerald-500/50' : 'bg-slate-50 border-slate-200 text-slate-800 focus:border-emerald-300'}`}
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
              <div className={`flex p-1 rounded-xl border ${darkMode ? 'bg-slate-950 border-slate-800' : 'bg-slate-100 border-slate-200'}`}>
                <button onClick={() => setViewMode('table')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all ${viewMode === 'table' ? (darkMode ? 'bg-slate-800 text-emerald-400' : 'bg-white text-slate-800 shadow-sm') : 'text-slate-500 hover:text-slate-700'}`}>Tabla</button>
                <button onClick={() => setViewMode('grid')} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all ${viewMode === 'grid' ? (darkMode ? 'bg-slate-800 text-emerald-400' : 'bg-white text-slate-800 shadow-sm') : 'text-slate-500 hover:text-slate-700'}`}>Cuadrícula</button>
              </div>
            </div>
          </div>

          {viewMode === 'table' ? (
            <div className={`rounded-2xl border overflow-hidden ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200 shadow-sm'}`}>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className={`text-[10px] uppercase font-bold tracking-[0.2em] ${darkMode ? 'bg-slate-950 text-slate-600' : 'bg-slate-50 text-slate-400'}`}>
                    <tr>
                      <th className="px-8 py-4">Cliente</th>
                      <th className="px-8 py-4">Responsable</th>
                      <th className="px-8 py-4">Ciudad</th>
                      <th className="px-8 py-4 text-right">Acciones</th>
                    </tr>
                  </thead>
                  <tbody className={`divide-y ${darkMode ? 'divide-slate-800' : 'divide-slate-100'}`}>
                    {filteredContacts.length > 0 ? filteredContacts.map((c) => (
                      <tr key={c.id} className={`group transition-all ${darkMode ? 'hover:bg-slate-800/20' : 'hover:bg-slate-50'}`}>
                        <td className="px-8 py-5">
                          <div className="flex items-center gap-3">
                             <div className={`font-bold text-sm ${darkMode ? 'text-slate-200' : 'text-slate-800'}`}>{c.client}</div>
                             <div className={`text-[9px] font-bold px-1.5 py-0.5 rounded border ${darkMode ? 'border-slate-800 text-slate-600' : 'border-slate-100 text-slate-400'}`}>{c.subClient || '---'}</div>
                          </div>
                        </td>
                        <td className="px-8 py-5"><div className={`text-sm font-medium ${darkMode ? 'text-slate-400' : 'text-slate-600'}`}>{c.contactName}</div></td>
                        <td className="px-8 py-5"><div className={`text-sm font-medium ${darkMode ? 'text-slate-400' : 'text-slate-600'}`}>{c.city}</div></td>
                        <td className="px-8 py-5 text-right">
                          <div className="flex gap-2 justify-end opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={() => openEditModal(c)} className={`p-1.5 rounded-lg ${darkMode ? 'text-slate-500 hover:text-emerald-400 hover:bg-slate-800' : 'text-slate-400 hover:text-emerald-600 hover:bg-slate-100'}`}><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 1 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
                            <button onClick={() => handleDeleteContact(c.id)} className={`p-1.5 rounded-lg ${darkMode ? 'text-slate-500 hover:text-rose-500 hover:bg-slate-800' : 'text-slate-400 hover:text-rose-600 hover:bg-slate-100'}`}><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>
                          </div>
                        </td>
                      </tr>
                    )) : (<tr><td colSpan={4} className="px-8 py-20 text-center text-slate-500 text-sm">Sin resultados</td></tr>)}
                  </tbody>
                </table>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {filteredContacts.length > 0 ? filteredContacts.map((c) => (
                <div key={c.id} className={`group rounded-2xl p-6 border transition-all ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
                  <div className="flex justify-between items-start mb-6">
                    <div className={`w-12 h-12 rounded-xl flex items-center justify-center ${darkMode ? 'bg-slate-950 text-emerald-500' : 'bg-slate-50 text-emerald-600'}`}><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z"/><path d="m3.3 7 8.7 5 8.7-5"/></svg></div>
                    <div className="flex gap-2">
                      <button onClick={() => openEditModal(c)} className={`p-2 rounded-lg ${darkMode ? 'text-slate-600 hover:text-emerald-400 hover:bg-slate-950' : 'text-slate-300 hover:text-emerald-600 hover:bg-slate-50'}`}><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 1 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
                      <button onClick={() => handleDeleteContact(c.id)} className={`p-2 rounded-lg ${darkMode ? 'text-slate-600 hover:text-rose-500 hover:bg-slate-950' : 'text-slate-300 hover:text-rose-600 hover:bg-slate-50'}`}><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>
                    </div>
                  </div>
                  <div className="mb-6"><h4 className={`text-lg font-bold mb-1 ${darkMode ? 'text-white' : 'text-slate-900'}`}>{c.client}</h4><p className={`text-[10px] font-bold uppercase tracking-widest ${darkMode ? 'text-slate-600' : 'text-slate-400'}`}>{c.subClient || 'Sin filial'}</p></div>
                  <div className="grid grid-cols-2 gap-6 mb-6">
                    <div><p className={`text-[10px] font-bold uppercase text-emerald-600 mb-1`}>Contacto</p><p className={`text-xs font-bold ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{c.contactName}</p><p className={`text-[11px] font-medium text-slate-500`}>{c.phone}</p></div>
                    <div><p className={`text-[10px] font-bold uppercase text-emerald-600 mb-1`}>Ubicación</p><p className={`text-xs font-bold ${darkMode ? 'text-slate-300' : 'text-slate-700'}`}>{c.city}</p><a href={getMapsUrl(c.address, c.city)} target="_blank" className={`text-[11px] font-medium text-slate-500 hover:text-emerald-500 flex items-center gap-1 mt-0.5`}>Mapa <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/></svg></a></div>
                  </div>
                  <div className={`p-4 rounded-xl text-[11px] leading-relaxed italic border border-dashed ${darkMode ? 'bg-slate-950/50 border-slate-800 text-slate-500' : 'bg-slate-50 border-slate-200 text-slate-500'}`}>{c.notes || 'Sin especificaciones.'}</div>
                </div>
              )) : (<div className="col-span-full py-20 text-center text-slate-500 italic">No se encontraron resultados</div>)}
            </div>
          )}
        </div>
      </main>

      <ContactModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveContact} initialData={currentContact} darkMode={darkMode} />
    </div>
  );
};

export default App;

